package com.franco.desco.adapter.out.sqlserver.pricing;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.pricing.*;import com.franco.desco.application.pricing.port.out.PricingPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.pricing.PricingModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class PricingSqlServerAdapter implements PricingPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall conditions,createCondition,updateCondition,disableCondition,prices,createPrice,versionPrice,history;public PricingSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;conditions=f.callWithResultSets("comercial","PA_CondicionComercial_Sel_Listado","items");createCondition=f.call("comercial","PA_CondicionComercial_Ins_Registro");updateCondition=f.call("comercial","PA_CondicionComercial_Upd_Registro");disableCondition=f.call("comercial","PA_CondicionComercial_Upd_Deshabilitar");prices=f.callWithResultSets("comercial","PA_PrecioComercial_Sel_Listado","items");createPrice=f.call("comercial","PA_PrecioComercial_Ins_Registro");versionPrice=f.callWithResultSets("comercial","PA_PrecioComercial_Ins_Version","versioned");history=f.callWithResultSets("comercial","PA_PrecioComercial_Sel_Historial","items");}
 public PersistenceResult<PageResult<PricingModels.Condition>>conditions(PricingCommands.ListConditions c,SessionIdentity i,RequestMetadata m){var pg=c.page();var out=e.executeJson(conditions,pf.forQuery(i,m,Map.of("paginacion",Map.of("pagina",pg.pagina(),"tamano",pg.tamanio()))));return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::condition,"No se pudieron consultar las condiciones.");}
 public PersistenceResult<Long>createCondition(PricingCommands.CreateCondition c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(createCondition,pf.forWrite(i,m,c,Map.of("condicion",map("modalidadVentaId",c.modalidadVentaId(),"codigo",c.codigo(),"nombre",c.nombre(),"descripcion",c.descripcion(),"pesoMinimoG",c.pesoMinimoG(),"pesoMaximoG",c.pesoMaximoG()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nCondicionComercialId"),"No se pudo crear la condición.");}public PersistenceResult<Void>updateCondition(PricingCommands.UpdateCondition c,SessionIdentity i,RequestMetadata m){return mut(updateCondition,i,m,c,"condicion",map("condicionComercialId",c.condicionComercialId(),"nombre",c.nombre(),"descripcion",c.descripcion(),"pesoMinimoG",c.pesoMinimoG(),"pesoMaximoG",c.pesoMaximoG()),"No se pudo actualizar la condición.");}public PersistenceResult<Void>disableCondition(PricingCommands.DisableCondition c,SessionIdentity i,RequestMetadata m){return mut(disableCondition,i,m,c,"condicion",map("condicionComercialId",c.condicionComercialId(),"motivo",c.motivo()),"No se pudo deshabilitar la condición.");}
 public PersistenceResult<PageResult<PricingModels.Price>>prices(PricingCommands.ListPrices c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var out=e.executeJson(prices,pf.forQuery(i,m,map("filtros",map("campaniaVentaId",f==null?null:f.campaniaVentaId(),"operativoVentaId",f==null?null:f.operativoVentaId(),"variedadPaltaId",f==null?null:f.variedadPaltaId(),"condicionComercialId",f==null?null:f.condicionComercialId()),"paginacion",map("pagina",pg.pagina(),"tamano",pg.tamanio()))));return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::price,"No se pudieron consultar los precios.");}
 public PersistenceResult<Long>createPrice(PricingCommands.CreatePrice c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(createPrice,pf.forWrite(i,m,c,Map.of("precio",map("campaniaVentaId",c.campaniaVentaId(),"operativoVentaId",c.operativoVentaId(),"variedadPaltaId",c.variedadPaltaId(),"condicionComercialId",c.condicionComercialId(),"precio",c.precio(),"moneda",c.moneda(),"unidadMedida",c.unidadMedida(),"fechaVigenciaDesde",c.fechaVigenciaDesde()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nPrecioComercialId"),"No se pudo crear el precio.");}
 public PersistenceResult<Long>versionPrice(PricingCommands.VersionPrice c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(versionPrice,pf.forWrite(i,m,c,Map.of("precio",map("precioComercialId",c.precioComercialId(),"precio",c.precio(),"fechaVigenciaDesde",c.fechaVigenciaDesde()))));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nPrecioComercialId"),"No se pudo versionar el precio.");}
 public PersistenceResult<List<PricingModels.PriceVersion>>history(PricingCommands.PriceHistory c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(history,pf.forQuery(i,m,Map.of("precio",Map.of("precioComercialId",c.precioComercialId()))));return PaAdapterSupport.result(out,rows(out,"items").stream().map(this::version).toList(),"No se pudo consultar el historial.");}
 private PersistenceResult<Void>mut(SimpleJdbcCall call,SessionIdentity i,RequestMetadata m,Object body,String root,Map<String,Object>v,String f){return PaAdapterSupport.result(e.executeJson(call,pf.forWrite(i,m,body,Map.of(root,v))),null,f);}private PricingModels.Condition condition(Map<String,Object>r){return new PricingModels.Condition(SqlValues.longValue(r,"condicionComercialId"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.string(r,"descripcion"),SqlValues.decimal(r,"pesoMinimoG"),SqlValues.decimal(r,"pesoMaximoG"),SqlValues.intValue(r,"modalidadVentaId"),SqlValues.string(r,"codigoModalidad"),SqlValues.string(r,"modalidad"),SqlValues.bool(r,"estado"),SqlValues.longValue(r,"usos"));}private PricingModels.Price price(Map<String,Object>r){return new PricingModels.Price(SqlValues.longValue(r,"precioComercialId"),SqlValues.longValue(r,"campaniaVentaId"),SqlValues.string(r,"campania"),SqlValues.longValue(r,"operativoVentaId"),SqlValues.string(r,"operativo"),SqlValues.intValue(r,"variedadPaltaId"),SqlValues.string(r,"variedad"),SqlValues.longValue(r,"condicionComercialId"),SqlValues.string(r,"condicion"),SqlValues.decimal(r,"precio"),SqlValues.string(r,"moneda"),SqlValues.string(r,"unidadMedida"),SqlValues.instant(r,"fechaVigenciaDesde"),SqlValues.instant(r,"fechaVigenciaHasta"),SqlValues.intValue(r,"version"),SqlValues.bool(r,"vigente"));}private PricingModels.PriceVersion version(Map<String,Object>r){return new PricingModels.PriceVersion(SqlValues.longValue(r,"precioComercialId"),SqlValues.decimal(r,"precio"),SqlValues.string(r,"moneda"),SqlValues.string(r,"unidadMedida"),SqlValues.instant(r,"fechaVigenciaDesde"),SqlValues.instant(r,"fechaVigenciaHasta"),SqlValues.intValue(r,"version"),SqlValues.bool(r,"estado"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
